50	\Require Proved formalization $x = \{c_1, \ldots, c_n\}$, solver $\mathcal{S}$
51	\Ensure Necessity vector $\mathbf{v} \in \{0,1\}^n$, ISR score
52	\For{$i = 1$ to $n$}
53	    \State $x_{\setminus i} \gets x \setminus \{c_i\}$ \Comment{Remove component $i$}
