55	\EndFor
56	\State $\text{ISR}(x) \gets \frac{1}{n} \sum_{i=1}^{n} v_i$
57	\State \Return $\mathbf{v}$, $\text{ISR}(x)$
58	\end{algorithmic}
59	\end{algorithm}
